/**
 * A2UI adapter — `a2ui-project/a2ui`, the canonical protocol project
 * (`google/A2UI` redirects here). Distinct from the `agenui` adapter, which
 * benchmarks AGenUI's third-party renderer SDK.
 *
 * Prompt: generated by A2UI's OWN Python SDK —
 * `a2ui_agent`'s `TransportFormat.prompt_generator.generate()` against the
 * standard v0.9 `basic` catalog (18 components). Vendored to
 * `vendor/a2ui-transport-prompt.txt` so runs are reproducible.
 *
 * `include_schema=True, include_examples=False`. Rationale, disclosed in the
 * report: with neither flag the prompt is 213 tokens and describes no
 * components at all, which would be an unwinnable configuration; with examples
 * it is ~49.6k tokens, four times any other prompt in the benchmark. Schema-only
 * (~10.1k) is the configuration a real integrator would ship.
 *
 * Validation: A2UI's own `TransportParser.parse_response()`, which performs
 * schema compilation and rejects malformed messages. Run through
 * `a2ui-python/a2ui_tool.py`, so the checking is entirely their code.
 *
 * Transport is A2UI's standard-JSON inference format. The project also ships
 * experimental `atom`, `elemental` and `express` formats which serialise more
 * compactly; those are not benchmarked here.
 */

import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { FormatAdapter, ValidationIssue, ValidationResult } from './types.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const PROMPT_FILE = join(ROOT, 'vendor', 'a2ui-transport-prompt.txt');
const TOOL = join(ROOT, 'a2ui-python', 'a2ui_tool.py');

/**
 * Interpreter with the A2UI SDK installed. The default lives under /tmp, which
 * the OS eventually cleans, so a missing interpreter is expected rather than
 * exceptional. Run `./a2ui-python/setup.sh` to rebuild it, or point
 * A2UI_PYTHON at a durable venv.
 */
const PYTHON = process.env.A2UI_PYTHON ?? '/tmp/a2ui-venv/bin/python';

const SYSTEM_PROMPT = existsSync(PROMPT_FILE) ? readFileSync(PROMPT_FILE, 'utf8') : '';

interface Verdict {
  ok: boolean;
  kind: string | null;
  message: string;
  components?: number;
  shape?: string;
}

/**
 * Validate a batch in one Python process. Spawning per generation would mean
 * ~270 interpreter startups; this keeps scoring to a single call.
 */
export function validateBatch(outputs: string[]): Verdict[] {
  if (outputs.length === 0) return [];
  const dir = mkdtempSync(join(tmpdir(), 'a2ui-batch-'));
  const file = join(dir, 'batch.jsonl');
  writeFileSync(file, outputs.map((o) => JSON.stringify({ output: o })).join('\n'), 'utf8');

  let stdout: string;
  try {
    stdout = execFileSync(PYTHON, [TOOL, 'validate', file], {
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
    });
  } catch (err) {
    const e = err as { code?: string };
    if (e.code === 'ENOENT') {
      throw new Error(
        `A2UI python environment missing at ${PYTHON}.\n` +
          `Rebuild it with:  ./a2ui-python/setup.sh\n` +
          `Or set A2UI_PYTHON to an interpreter with the a2ui SDK installed.`,
      );
    }
    throw err;
  }
  return stdout
    .split('\n')
    .filter(Boolean)
    .map((l) => JSON.parse(l) as Verdict);
}

/** Cache so repeated single-output validation during scoring stays cheap. */
const cache = new Map<string, Verdict>();

export function primeCache(outputs: string[]): void {
  const missing = outputs.filter((o) => !cache.has(o));
  if (missing.length === 0) return;
  const verdicts = validateBatch(missing);
  missing.forEach((o, i) => cache.set(o, verdicts[i]));
}

function toResult(v: Verdict): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (!v.ok) {
    issues.push({
      kind: (v.kind as ValidationIssue['kind']) ?? 'schema-error',
      message: v.message,
    });
  }
  return { ok: v.ok, issues, shape: v.shape, componentCount: v.components ?? 0 };
}

export const a2uiTransportAdapter: FormatAdapter = {
  id: 'a2ui',
  label: 'A2UI (transport)',
  promptSource: "a2ui_agent TransportFormat.prompt_generator.generate() — A2UI's own Python SDK",

  async systemPrompt(): Promise<string> {
    if (!SYSTEM_PROMPT) {
      throw new Error(
        `missing ${PROMPT_FILE} — regenerate with:\n  ${PYTHON} ${TOOL} prompt > ${PROMPT_FILE}`,
      );
    }
    return SYSTEM_PROMPT;
  },

  validate(output: string): ValidationResult {
    const hit = cache.get(output);
    if (hit) return toResult(hit);
    const [verdict] = validateBatch([output]);
    cache.set(output, verdict);
    return toResult(verdict);
  },
};
